import java.util.HashSet;
import java.util.Set;

class Solution {
    public int[] distinctDifferenceArray(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        int[] suffixDistinct = new int[n + 1];

        Set<Integer> seen = new HashSet<>();
        for (int i = n - 1; i >= 0; i--) {
            seen.add(nums[i]);
            suffixDistinct[i] = seen.size();
        }

        seen.clear();
        for (int i = 0; i < n; i++) {
            seen.add(nums[i]);
            answer[i] = seen.size() - suffixDistinct[i + 1];
        }
        return answer;
    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

class Solution {
    public int[] distinctDifferenceArray(int[] nums) {
        Map<Integer, Integer> suffix = new HashMap<>();
        for (int num : nums) {
            suffix.put(num, suffix.getOrDefault(num, 0) + 1);
        }

        Set<Integer> prefix = new HashSet<>();
        int suffixDistinct = suffix.size();
        int[] answer = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            prefix.add(nums[i]);

            int remaining = suffix.get(nums[i]) - 1;
            if (remaining == 0) {
                suffix.remove(nums[i]);
                suffixDistinct--;
            } else {
                suffix.put(nums[i], remaining);
            }

            answer[i] = prefix.size() - suffixDistinct;
        }
        return answer;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int[] distinctDifferenceArray(int[] nums) {
        int n = nums.length;
        Map<Integer, Integer> first = new HashMap<>();
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < n; i++) {
            first.putIfAbsent(nums[i], i);
            last.put(nums[i], i);
        }

        int[] prefixGain = new int[n];
        int[] suffixDelta = new int[n + 1];
        for (int value : first.keySet()) {
            int firstIndex = first.get(value);
            int lastIndex = last.get(value);
            prefixGain[firstIndex]++;
            if (lastIndex > 0) {
                suffixDelta[0]++;
                suffixDelta[lastIndex]--;
            }
        }

        int prefixDistinct = 0;
        int suffixDistinct = 0;
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            prefixDistinct += prefixGain[i];
            suffixDistinct += suffixDelta[i];
            answer[i] = prefixDistinct - suffixDistinct;
        }
        return answer;
    }
}

import java.util.Arrays;

class Solution {
    public int[] distinctDifferenceArray(int[] nums) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);

        int unique = 0;
        for (int num : sorted) {
            if (unique == 0 || sorted[unique - 1] != num) {
                sorted[unique++] = num;
            }
        }

        int[] left = new int[unique];
        int[] right = new int[unique];
        for (int num : nums) {
            right[indexOf(sorted, unique, num)]++;
        }

        int leftDistinct = 0;
        int rightDistinct = unique;
        int[] answer = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int id = indexOf(sorted, unique, nums[i]);
            if (left[id]++ == 0) {
                leftDistinct++;
            }
            if (--right[id] == 0) {
                rightDistinct--;
            }
            answer[i] = leftDistinct - rightDistinct;
        }
        return answer;
    }

    private int indexOf(int[] sorted, int unique, int target) {
        int lo = 0;
        int hi = unique - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (sorted[mid] == target) {
                return mid;
            }
            if (sorted[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return -1;
    }
}
